          _totalEarnings = (wallet['total_earned'] as num?)
              ?.toStringAsFixed(0) ?? '0';
          _pendingPayouts = (wallet['pending_amount'] as num?)
              ?.toStringAsFixed(0) ?? '0';
        });
      }
    } catch (e) {
      debugPrint('Error loading earnings: $e');
    }
  }

